<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Booking; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class ResourceController extends Controller {
 private array $map=['customers'=>[\App\Models\Customer::class,['name'=>'required','mobile'=>'required|max:20','email'=>'nullable|email']], 'menu-items'=>[\App\Models\MenuItem::class,['name'=>'required','category'=>'required']], 'packages'=>[\App\Models\SadyaPackage::class,['name'=>'required','price_per_leaf'=>'required|numeric|min:0']], 'expenses'=>[\App\Models\Expense::class,['date'=>'required|date','expense_type'=>'required|string','description'=>'required','amount'=>'required|numeric|min:0','payment_method'=>'nullable','booking_id'=>'nullable|exists:bookings,id','supplier_id'=>'nullable|exists:suppliers,id','quantity'=>'nullable|numeric|min:0','rate'=>'nullable|numeric|min:0']], 'payments'=>[\App\Models\Payment::class,['booking_id'=>'required|exists:bookings,id','payment_date'=>'required|date','amount'=>'required|numeric|min:0.01','payment_mode'=>'required','payment_type'=>'required']], 'suppliers'=>[\App\Models\Supplier::class,['name'=>'required|string|max:255','mobile'=>'nullable|max:20']], 'purchase-types'=>[\App\Models\PurchaseType::class,['name'=>'required|string|max:255']]];
 public function storePurchase(Request $r){$r->merge(['expense_type'=>'Purchase']);return $this->store($r,'expenses');}
 public function updatePurchase(Request $r,int $id){abort_unless(\App\Models\Expense::findOrFail($id)->expense_type==='Purchase',404);$r->merge(['expense_type'=>'Purchase']);return $this->update($r,$id,'expenses');}
 private function validateExpenseType(Request $r,$item=null){
  if($r->routeIs('purchases.*'))return;
  if(is_string($r->paid_to))$r->merge(['paid_to'=>preg_replace('/\s+/u',' ',trim($r->paid_to))]);
  $r->validate(['paid_to'=>'required|string|max:255']);
  if(($item && mb_strtolower(trim($item->expense_type))==='purchase') || ($r->has('expense_type') && is_string($r->expense_type) && mb_strtolower(trim($r->expense_type))==='purchase'))throw ValidationException::withMessages(['expense_type'=>'Add or edit purchases from the Purchases tab.']);
 }
 public function payees(Request $r){$r->validate(['expense_type'=>'nullable|string']);return \App\Models\Expense::query()->when(!$r->boolean('include_purchases'),fn($q)=>$q->whereRaw('lower(trim(expense_type)) != ?', ['purchase']))->when($r->filled('expense_type'),fn($q)=>$q->where('expense_type',$r->expense_type))->whereNotNull('paid_to')->orderBy('id')->pluck('paid_to')->map(fn($name)=>preg_replace('/\s+/u',' ',trim($name)))->filter()->unique(fn($name)=>mb_strtolower($name))->sortBy(fn($name)=>mb_strtolower($name))->values();}
 private function cfg(string $resource){abort_unless(isset($this->map[$resource]),404);return $this->map[$resource];}
 public function index(Request $r,string $resource){[$m]=$this->cfg($resource);$q=$m::query();if(in_array($resource,['customers','suppliers'])&&$r->search)$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('mobile','like','%'.$r->search.'%'));if($resource==='purchase-types'&&$r->search)$q->where('name','like','%'.$r->search.'%');if($resource==='packages')$q->with('items');if($resource==='expenses'){$q->with(['booking','category','supplier','payments','items']);if($r->boolean('exclude_purchases'))$q->whereRaw('lower(trim(expense_type)) != ?', ['purchase']);if($r->expense_type)$q->where('expense_type',$r->expense_type);
 $r->validate(['sort'=>'nullable|in:date,expense_type,paid_to','direction'=>'nullable|in:asc,desc','payment_status'=>'nullable|in:pending,paid','paid_to'=>'nullable|string|max:255']);
 if($r->filled('paid_to'))$q->where('paid_to','like','%'.$r->paid_to.'%');
 if($r->payment_status){$operator=$r->payment_status==='pending'?'>':'<=';$q->whereRaw("expenses.amount $operator (select coalesce(sum(amount),0) from expense_payments where expense_payments.expense_id = expenses.id)");}
 $sort=$r->input('sort')?:'date';$direction=$r->input('direction')?:'desc';
 if(in_array($sort,['expense_type','paid_to']))$q->orderByRaw("lower(trim($sort)) $direction");else $q->orderBy('date',$direction);
 $q->orderByDesc('id');if($r->search)$q->where(fn($x)=>$x->where('description','like','%'.$r->search.'%')->orWhere('item_name','like','%'.$r->search.'%')->orWhere('invoice_number','like','%'.$r->search.'%')->orWhereHas('supplier',fn($s)=>$s->where('name','like','%'.$r->search.'%'))->orWhereHas('items',fn($i)=>$i->where('item_name','like','%'.$r->search.'%')));}if($resource==='payments')$q->with('booking.customer');return $q->latest()->paginate($r->integer('per_page',25));}
 public function store(Request $r,string $resource){if($resource==='expenses')$this->validateExpenseType($r);[$m,$rules]=$this->cfg($resource);if($resource==='expenses')$rules+=['items'=>'nullable|array|min:1','items.*.item_name'=>'required_with:items|string','items.*.amount'=>'required_with:items|numeric|min:0.01'];$data=$r->validate($rules);if(in_array($resource,['suppliers','purchase-types'])){$name=trim($data['name']);$existing=$m::whereRaw('lower(name) = ?',[mb_strtolower($name)])->first();if($existing)return response()->json($existing);$data['name']=$name;return response()->json($m::create($data+$r->all()),201);}if($resource==='payments'){return DB::transaction(function()use($m,$data){$booking=Booking::with('payments')->lockForUpdate()->findOrFail($data['booking_id']);$balance=max(0,$booking->final_amount-$booking->payments->sum('amount'));if($data['amount']>$balance)throw ValidationException::withMessages(['amount'=>'Payment cannot exceed the outstanding balance.']);return response()->json($m::create($data)->load('booking.customer'),201);});}if($resource==='expenses')return $this->storeExpense($r,$m,$data);$item=$m::create($data+$r->all());if($resource==='packages'&&$r->has('item_ids'))$item->items()->sync($r->item_ids);return response()->json($item->fresh(),201);}
 private function storeExpense(Request $r,string $m,array $data){$items=collect($data['items']??[])->map(fn($i)=>$i+['amount'=>round($i['amount'],2)]);unset($data['items']);if($items->isNotEmpty())$data['amount']=round($items->sum('amount'),2);elseif($data['expense_type']==='Purchase'&&isset($data['quantity'],$data['rate']))$data['amount']=round($data['quantity']*$data['rate'],2);$initial=$r->filled('initial_payment')?(float)$r->initial_payment:0;if($initial<0||$initial>$data['amount'])throw ValidationException::withMessages(['initial_payment'=>'Initial payment must be between zero and the expense total.']);if($initial>0&&!$r->filled('payment_method'))throw ValidationException::withMessages(['payment_method'=>'Choose a payment method for the initial payment.']);return DB::transaction(function()use($m,$data,$r,$initial,$items){$item=$m::create($data+$r->except(['initial_payment','items']));if($items->isNotEmpty())$item->items()->createMany($items->all());if($initial>0)$item->payments()->create(['payment_date'=>$data['date'],'amount'=>$initial,'payment_method'=>$data['payment_method']]);return response()->json($item->load(['booking','category','supplier','payments','items'])->fresh(),201);});}
 public function show(int $id,string $resource){[$m]=$this->cfg($resource);if($resource==='customers'){$customer=$m::with(['bookings'=>fn($q)=>$q->with(['package','payments','expenses'])->orderByDesc('function_date')])->findOrFail($id);$customer->bookings->each->append(['paid_amount','balance_amount','estimated_profit']);$customer->setAttribute('total_business_value',(float)$customer->bookings->where('status','!=','Cancelled')->sum('final_amount'));$customer->setAttribute('pending_payments',(float)$customer->bookings->sum('balance_amount'));return $customer;}if($resource==='expenses')return $m::with(['booking','category','supplier','payments','items'])->findOrFail($id);return $m::findOrFail($id);}
 public function update(Request $r,int $id,string $resource){[$m,$rules]=$this->cfg($resource);if($resource==='expenses')$rules+=['items'=>'sometimes|array|min:1','items.*.item_name'=>'sometimes|string','items.*.amount'=>'sometimes|numeric|min:0.01'];$item=$m::findOrFail($id);if($resource==='expenses')$this->validateExpenseType($r,$item);$data=$r->validate(array_map(fn($v)=>str_replace('required','sometimes',$v),$rules));$items=collect($data['items']??[])->map(fn($i)=>$i+['amount'=>round($i['amount'],2)]);unset($data['items']);if($resource==='expenses'&&$items->isNotEmpty())$data['amount']=round($items->sum('amount'),2);elseif($resource==='expenses'&&($data['expense_type']??$item->expense_type)==='Purchase'){$quantity=$data['quantity']??$item->quantity;$rate=$data['rate']??$item->rate;if($quantity!==null&&$rate!==null)$data['amount']=round($quantity*$rate,2);}$item->update($data+$r->except(['initial_payment','items']));if($resource==='expenses'&&$r->has('items')){$item->items()->delete();$item->items()->createMany($items->all());}if($resource==='packages'&&$r->has('item_ids'))$item->items()->sync($r->item_ids);return $item->fresh();}
 public function destroy(int $id,string $resource){[$m]=$this->cfg($resource);$m::findOrFail($id)->delete();return response()->noContent();}
}
